<?php defined('_JEXEC') or die;use Joomla\CMS\Router\Route;?>
<form method="get" action="<?php echo Route::_('index.php?option=com_sanctuaryshop&view=reports'); ?>" class="mb-4"><input type="hidden" name="option" value="com_sanctuaryshop"><input type="hidden" name="view" value="reports"><div class="row g-2 align-items-end"><div class="col-md-3"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?php echo $this->escape($this->from); ?>"></div><div class="col-md-3"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?php echo $this->escape($this->to); ?>"></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['completed','processing','pending','cancelled','refunded'] as $s): ?><option value="<?php echo $s; ?>"<?php echo $this->status===$s?' selected':''; ?>><?php echo ucfirst($s); ?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn btn-primary">Run report</button></div></div></form>
<?php $sym='$';$s=$this->summary;?><div class="row g-3 mb-4"><?php foreach([['Orders','orders',true],['Revenue','revenue',false],['Tax','tax',false],['Shipping','shipping',false]] as $x):?><div class="col-md-3"><div class="card"><div class="card-body"><div class="h4"><?php echo $x[2]?(int)($s->{$x[1]}??0):$sym.' '.number_format((float)($s->{$x[1]}??0),2);?></div><div class="text-muted"><?php echo $x[0];?></div></div></div></div><?php endforeach;?></div>
<div class="row g-4"><div class="col-lg-6"><div class="card"><div class="card-header fw-semibold">Orders by status</div><table class="table mb-0"><tbody><?php foreach($this->statuses as $r):?><tr><td><?php echo $this->escape($r->value);?></td><td><?php echo (int)$r->orders;?></td><td class="text-end"><?php echo $sym.number_format((float)$r->revenue,2);?></td></tr><?php endforeach;?></tbody></table></div></div><div class="col-lg-6"><div class="card"><div class="card-header fw-semibold">Sales by payment provider</div><table class="table mb-0"><tbody><?php foreach($this->providers as $r):?><tr><td><?php echo $this->escape($r->value?:'unknown');?></td><td><?php echo (int)$r->orders;?></td><td class="text-end"><?php echo $sym.number_format((float)$r->revenue,2);?></td></tr><?php endforeach;?></tbody></table></div></div><div class="col-12"><div class="card"><div class="card-header fw-semibold">Top completed products</div><table class="table mb-0"><tbody><?php foreach($this->products as $r):?><tr><td><?php echo $this->escape($r->title);?></td><td><?php echo (int)$r->quantity;?></td><td class="text-end"><?php echo $sym.number_format((float)$r->revenue,2);?></td></tr><?php endforeach;?></tbody></table></div></div></div>